// Runs after a workflow's own retries are exhausted. Swap for Slack/email/
// PagerDuty in production. The error message is logged, the payload is not.
const { workflow, execution } = $input.first().json;
const alert = {
  workflow: workflow?.name,
  failedNode: execution?.lastNodeExecuted,
  error: execution?.error?.message,
  executionUrl: execution?.url,
  at: new Date().toISOString(),
};
console.log('[alert] LendLoop automation failed', JSON.stringify(alert));
return [{ json: alert }];
